/// <summary>
/// Service class for order total recalculation operations.
/// </summary>
internal final class SOrderRecalculateService
{
}

Method.Source:
/// <summary>
/// Recalculates the total amount for the specified order.
/// </summary>
/// <param name="_contract">Contract containing the order ID.</param>
public void process(SOrderRecalculateContract _contract)
{
    SOrderService::recalculateTotal(_contract.parmOrderId());
}
